function render(){if(!sourceData)return;const d=sourceData.data,out=new Uint8ClampedArray(d.length),e=state.edits,exp=Math.pow(2,Number(e.exposure)||0),contrast=(Number(e.contrast)+(Number(e.clarity)||0)*.28+(Number(e.dehaze)||0)*.18)/100,sat=(Number(e.saturation)+(Number(e.vibrance)||0)*.55)/100,temp=(Number(e.temp)||0)/100,hi=(Number(e.highlights)||0)/100,sh=(Number(e.shadows)||0)/100,wh=(Number(e.whites)||0)/100,bl=(Number(e.blacks)||0)/100,maskExp=Math.pow(2,Number(e.maskExposure)||0),md=state.maskData;for(let i=0,p=0;i<d.length;i+=4,p++){let r=d[i]/255,g=d[i+1]/255,b=d[i+2]/255;r*=exp;g*=exp;b*=exp;let l=.2126*r+.7152*g+.0722*b;if(l>.5){const q=hi*(l-.5)*.55;r+=q;g+=q;b+=q}if(l<.5){const q=sh*(.5-l)*.55;r+=q;g+=q;b+=q}if(l>.75){const q=wh*((l-.75)/.25)*.18;r+=q;g+=q;b+=q}if(l<.25){const q=bl*((.25-l)/.25)*.18;r+=q;g+=q;b+=q}r=(r-.5)*(1+contrast)+.5;g=(g-.5)*(1+contrast)+.5;b=(b-.5)*(1+contrast)+.5;r+=temp*.10;b-=temp*.10;l=.2126*r+.7152*g+.0722*b;r=l+(r-l)*(1+sat);g=l+(g-l)*(1+sat);b=l+(b-l)*(1+sat);if(md&&md[p]>0){const a=md[p]/255,me=1+(maskExp-1)*a;r*=me;g*=me;b*=me}if(state.highlightGuard){const mx=Math.max(r,g,b);if(mx>1){const q=1/mx;r*=q;g*=q;b*=q}}out[i]=clamp(r)*255;out[i+1]=clamp(g)*255;out[i+2]=clamp(b)*255;out[i+3]=255}workCtx.putImageData(new ImageData(out,sourceData.width,sourceData.height),0,0);applyHeal(workCtx,state.healApplied);if(state.healPreview)applyHeal(workCtx,state.healProposals.filter(x=>x.enabled));renderOutput();renderMask();renderHeal();saveSoon()}
