function sourceToOutput(sx,sy){const spec=outputSpec(false),cx=spec.sx+spec.sw/2,cy=spec.sy+spec.sh/2,dx=sx-cx,dy=sy-cy;if(spec.c.flipH)dx=-dx;if(spec.c.flipV)dy=-dy;const a=(spec.c.rotate||0)*Math.PI/180,rx=dx*Math.cos(a)-dy*Math.sin(a),ry=dx*Math.sin(a)+dy*Math.cos(a);return{x:editCanvas.width/2+rx,y:editCanvas.height/2+ry,scale:1}}
