function tech(){if(!sourceData)return{lum:.5,bright:0,dark:0,dynamic:.4};const d=sourceData.data,vals=[];let lum=0,bright=0,dark=0,n=0,step=Math.max(4,Math.floor((d.length/4)/18000)*4);for(let i=0;i<d.length;i+=step){const l=.2126*d[i]/255+.7152*d[i+1]/255+.0722*d[i+2]/255;lum+=l;if(l>.97)bright++;if(l<.05)dark++;vals.push(l);n++}vals.sort((a,b)=>a-b);return{lum:lum/n,bright:bright/n,dark:dark/n,dynamic:(vals[Math.floor(vals.length*.9)]||.8)-(vals[Math.floor(vals.length*.1)]||.2)}}
function scene(){const ls=labelMap(state.analysis),text=ls.map(x=>x.t).join(' '),t=tech(),people=!!(state.analysis?.peopleEvidence||state.analysis?.poseDetected||(state.analysis?.faces||[]).length||/person|portrait|human|fashion|child|man|woman/.test(text)),wedding=/wedding|bride|groom/.test(text),arch=/architecture|building|facade|cathedral|church|basilica|tower|monument|landmark/.test(text),coast=/sea|ocean|beach|coast|water/.test(text);if(wedding)return{name:'Wedding',preset:'Wedding Glow',why:'Protects skin and white fabric while keeping an elegant, natural atmosphere.'};if(people)return{name:'People',preset:'Portrait Clean',why:'Prioritizes natural skin, controlled highlights and gentle subject separation.'};if(arch&&coast)return{name:'Coastal Architecture',preset:'Coastal Architecture',why:'Balances building detail, sky and sea while keeping Mediterranean color natural.'};if(/church|cathedral|basilica/.test(text))return{name:'Architecture',preset:'Cathedral Luminous',why:'Protects bright stone and windows while revealing architectural detail.'};if(arch)return{name:'Architecture',preset:'Architecture Detail',why:'Strengthens structure and detail without oversaturating the scene.'};if(coast)return{name:'Travel',preset:'Coastal Story',why:'Adds controlled depth and color for coastal and travel scenes.'};if(t.lum<.27)return{name:'Night',preset:'Night Mood',why:'Lifts useful shadow detail while keeping night contrast and highlights controlled.'};if(t.bright>.035)return{name:'Bright scene',preset:'Cloudy Soft',why:'Recovers bright detail and keeps color restrained.'};return{name:'General',preset:'Natural Clean',why:'Balanced technical starting point for the current image.'}}
