function ratePanel(){const t=tech(),s=scene(),straight=estimateStraighten(),cropNeeded=s.name==='People'||s.name==='Architecture'||s.name==='Coastal Architecture',technical=clamp(9.4-Math.abs(t.lum-.5)*3.2-t.bright*8,5,9.8),creative=s.name==='General'?8.3:8.8,potential=clamp(Math.max(technical,creative)+.7,0,10),fixes=[];if(cropNeeded)fixes.push(['Crop for stronger framing','Tighten composition while preserving the main subject','crop']);if(Math.abs(straight)>.25||/Architecture/.test(s.name))fixes.push(['Straighten and vertical correction',`Suggested straighten ${straight>=0?'+':''}${straight.toFixed(1)}°`,'straight']);if(t.bright>.01)fixes.push(['Protect highlights','Recover useful detail in bright areas','tone']);if(t.lum<.48)fixes.push(['Lift shadow detail','Reveal detail without flattening contrast','tone']);fixes.push(['Refine local color','Keep natural color and reduce haze','color']);if(state.healApplied.length===0)fixes.push(['Remove distractions','Review small distractions before removal','heal']);$('#panelBody').innerHTML=`<div class="scoreWrap"><div class="score"><b>${technical.toFixed(1)}</b><small>Technical</small></div><div class="score"><b>${creative.toFixed(1)}</b><small>Creative</small></div><div class="score"><b>${potential.toFixed(1)}</b><small>Potential</small></div></div><h3>What to improve</h3><div class="fixList">${fixes.map((f,i)=>`<button class="fix" data-f="${f[2]}"><i>${i+1}</i><div><b>${f[0]}</b><small>${f[1]}</small></div><span>›</span></button>`).join('')}</div><button class="primary wide" id="applyRate">Apply Suggested Tone Fixes</button><div class="rowBtns" style="margin-top:9px"><button class="secondary" id="previewRate">Preview All</button><button class="secondary" id="reviewRate">Review Individually</button></div>`;$$('[data-f]').forEach(b=>b.onclick=()=>{if(b.dataset.f==='crop'||b.dataset.f==='straight'){openTool('crop');if(b.dataset.f==='straight'){state.cropDraft.rotate=straight;cropPanel()}}else if(b.dataset.f==='heal')openTool('heal');else if(b.dataset.f==='color')openTool('color');else openTool('smart')});$('#applyRate').onclick=()=>{pushHistory();state.edits.highlights=Math.min(state.edits.highlights,-30);state.edits.shadows=Math.max(state.edits.shadows,20);state.edits.vibrance=Math.max(state.edits.vibrance,8);render();toast('Tone fixes applied · crop and removals remain reviewable')};$('#previewRate').onclick=()=>toast('Open each listed fix to preview geometry or local changes');$('#reviewRate').onclick=()=>openTool(fixes[0]?.[2]==='heal'?'heal':'crop')}

function openTool(name,rerender=true){state.tool=name;$$('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===name));$('#maskToggle').classList.add('hidden');if(name!=='crop'){state.cropDraft=null;$('#cropOverlay').classList.add('hidden')}const titles={smart:['Smart Edit','Analyze · suggest · preview · apply'],presets:['Presets','Scene-based smart presets'],light:['Light','Professional tone'],color:['Color & Skin','Skin-aware color'],detail:['Detail','Texture and atmospheric detail'],mask:['Masks','Smart semantic masks + brush refinement'],heal:['Heal / Remove','Review removals before applying'],crop:['Crop & Straighten','Precise geometry · professional output'],rate:['Rate & Improve','Technical · Creative · Potential']},t=titles[name]||[name,''];$('#panelTitle').textContent=t[0];$('#panelHint').textContent=t[1];$('#resetBtn').style.display=['light','color','detail','mask'].includes(name)?'block':'none';if(name==='smart')smartPanel();if(name==='presets')presetsPanel();if(name==='light')lightPanel();if(name==='color')colorPanel();if(name==='detail')detailPanel();if(name==='mask')maskPanel();if(name==='heal')healPanel();if(name==='crop')cropPanel();if(name==='rate')ratePanel();if(rerender)render();requestAnimationFrame(()=>{if(name==='crop')positionCropOverlay();else fitIfNeeded()})}
function saveSoon(){clearTimeout(saveTimer);saveTimer=setTimeout(saveCurrent,450)}
async function saveCurrent(){if(!current||!editCanvas.width)return;current.edits={...state.edits};current.crop07=JSON.parse(JSON.stringify(state.crop));current.healApplied=JSON.parse(JSON.stringify(state.healApplied));current.favorite=state.favorite;current.edited=Object.keys(DEFAULTS).some(k=>Math.abs(Number(state.edits[k]||0)-Number(DEFAULTS[k]||0))>.001)||state.crop.rect.w<.999||state.crop.rect.h<.999||Math.abs(state.crop.rotate||0)>.01||state.healApplied.length>0;const c=document.createElement('canvas'),x=c.getContext('2d'),s=Math.min(1,500/Math.max(editCanvas.width,editCanvas.height));c.width=Math.max(1,Math.round(editCanvas.width*s));c.height=Math.max(1,Math.round(editCanvas.height*s));x.drawImage(editCanvas,0,0,c.width,c.height);current.editedThumb=c.toDataURL('image/jpeg',.82);current.modified=Date.now();await dbPut(current).catch(()=>{});const i=library.findIndex(r=>r.id===current.id);if(i>=0)library[i]=current}
function exportPhoto(){render();const d=actualCropDims(),maxOut=6000,scale=Math.min(1,maxOut/Math.max(d.w,d.h)),ow=Math.max(1,Math.round(d.w*scale)),oh=Math.max(1,Math.round(d.h*scale)),out=document.createElement('canvas');out.width=ow;out.height=oh;out.getContext('2d').drawImage(editCanvas,0,0,ow,oh);try{FrameAndroid.saveJpeg(out.toDataURL('image/jpeg',.95),'FRAME_'+Date.now()+'.jpg');toast(`Exported ${ow} × ${oh}`)}catch(e){toast('Export unavailable')}}

let pointers=new Map(),pinchStart=0,zoomStart=1,panStart=null;
function pointerDown(e){if(state.tool==='mask'){pushHistory(true);painting=true;paintMask(e);return}if(state.tool==='heal'){const p=canvasPoint(e);if(p){state.healProposals.push({id:++healSeq,x:p.x/sourceCanvas.width,y:p.y/sourceCanvas.height,r:state.brushSize,enabled:true});render();healPanel();toast('Removal proposed · review before apply')}return}$('#viewport').setPointerCapture?.(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1)panStart={x:e.clientX,y:e.clientY,px:state.panX,py:state.panY};if(pointers.size===2){const a=[...pointers.values()];pinchStart=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);zoomStart=state.zoom}}
function pointerMove(e){if(state.tool==='mask'&&painting){paintMask(e);return}if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);state.zoom=clamp(zoomStart*d/Math.max(1,pinchStart),1,8);applyView()}else if(pointers.size===1&&state.zoom>1.01&&panStart){state.panX=panStart.px+(e.clientX-panStart.x);state.panY=panStart.py+(e.clientY-panStart.y);applyView()}}
function pointerUp(e){painting=false;pointers.delete(e.pointerId);if(!pointers.size)panStart=null}

function showSetting(kind){const title={ai:'AI & Analysis',presets:'Preset Management',library:'Library & Storage',export:'Export Settings',appearance:'App Appearance',backup:'Backup & Restore',help:'Help & Support'}[kind]||'Settings';$('#modalTitle').textContent=title;let html='';if(kind==='ai')html=`<label class="setting"><div><b>Highlight Guard</b><small>Automatic and silent</small></div><input id="mHi" type="checkbox" ${state.highlightGuard?'checked':''}></label><label class="setting"><div><b>Skin Priority</b><small>Used when people are reliably detected</small></div><input id="mSkin" type="checkbox" ${state.skinPriority?'checked':''}></label>`;if(kind==='presets')html=`<p>${Object.keys(customPresets()).length} custom presets saved.</p><button class="secondary wide" id="mPreset">Open Presets</button>`;if(kind==='library')html=`<p><b>${library.length}</b> photos stored in FRAME. Originals remain on your device.</p><p>Edited: ${library.filter(x=>x.edited).length} · Favorites: ${library.filter(x=>x.favorite).length}</p>`;if(kind==='export')html=`<label>JPEG Quality <input id="mQuality" type="range" min="80" max="100" value="95"></label><p>Export keeps the crop's real pixel dimensions up to 6000 px on the longest side.</p>`;if(kind==='appearance')html='<p>Essential Professional theme is locked for this beta to preserve mockup fidelity.</p>';if(kind==='backup')html='<button class="secondary wide" id="mBackup">Copy configuration snapshot</button><textarea id="backupText" style="width:100%;min-height:130px;margin-top:10px;background:#080a0c;color:#ddd;border:1px solid #333;border-radius:10px"></textarea>';if(kind==='help')html='<p>Beta 0.7 diagnostics: verify Library → Fit/Zoom → Smart → Mask → Crop 9:16 → Heal approval → Export.</p>';$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');if($('#mHi'))$('#mHi').onchange=e=>{state.highlightGuard=e.target.checked;localStorage.setItem('frameHighlight',e.target.checked?'1':'0')};if($('#mSkin'))$('#mSkin').onchange=e=>{state.skinPriority=e.target.checked;localStorage.setItem('frameSkin',e.target.checked?'1':'0')};if($('#mPreset'))$('#mPreset').onclick=()=>{$('#modal').classList.add('hidden');if(current){show('editor');openTool('presets')}else toast('Open a photo first')};if($('#mBackup'))$('#mBackup').onclick=()=>{$('#backupText').value=JSON.stringify({customPresets:customPresets(),highlightGuard:state.highlightGuard,skinPriority:state.skinPriority},null,2);$('#backupText').select();document.execCommand?.('copy');toast('Backup snapshot copied')}}

